const grandParent = {
  country: "India"
};

const parent = Object.create(grandParent);
parent.city = "Kolkata";

const child = Object.create(parent);
child.name = "Jeet";

console.log(child.name);    // Jeet
console.log(child.city);    // Kolkata
console.log(child.country); // India

// Chain:
// child → parent → grandParent → Object.prototype → null

const person = {
  greet() {
    console.log("Hello");
  }
};

const user = Object.create(person);

console.log(user.__proto__ === person); // true

// Preferred way to read the prototype
console.log(Object.getPrototypeOf(user) === person); // true

function User(name) {
  this.name = name;
}

User.prototype.greet = function () {
  console.log(`Hello, ${this.name}`);
};

const user1 = new User("Jeet");
const user2 = new User("John");

user1.greet(); // Hello, Jeet
user2.greet(); // Hello, John

console.log(Object.getPrototypeOf(user1) === User.prototype);
// true

