function User(name) {
  this.name = name;
}

User.prototype.sayHello = function () {
  return `Hello, ${this.name}`;
};

const user1 = new User("Jeet");
const user2 = new User("John");

console.log(user1.sayHello()); // Hello, Jeet
console.log(user2.sayHello()); // Hello, John

